1	// tiled_gemm_s8: tile-sequencing wrapper around an 8x16 PE grid.
2	// Decomposes arbitrary M×K×N GEMMs into ceil(M/8)×ceil(N/16) tiles,
3	// processing each sequentially with boundary zero-padding.
4	module tiled_gemm_s8 #(
5	    parameter PM       = 8,
6	    parameter PN       = 16,
7	    parameter A_LEN    = 65536,
8	    parameter B_LEN    = 65536,
9	    parameter C_LEN    = 16384,
10	    parameter BIAS_LEN = 1024,
11	    parameter DIM_W    = 16
12	)(
13	    input                clk,
14	    input                rst_n,
15	    input                start,
16	    input  [DIM_W-1:0]   M_in,
17	    input  [DIM_W-1:0]   K_in,
18	    input  [DIM_W-1:0]   N_in,
19	    input                use_bias,
20	    output reg           done
21	);
22	
23	    reg signed [7:0]  a_buf    [0:A_LEN-1];
24	    reg signed [7:0]  b_buf    [0:B_LEN-1];
25	    reg signed [31:0] bias_buf [0:BIAS_LEN-1];
26	    reg signed [31:0] c_buf    [0:C_LEN-1];
27	
28	    // FSM states
29	    localparam S_IDLE    = 3'd0;
30	    localparam S_COMPUTE = 3'd1;
31	    localparam S_DRAIN   = 3'd2;
32	    localparam S_NEXT    = 3'd3;
33	    localparam S_DONE    = 3'd4;
34	
35	    reg [2:0] state;
36	
37	    // Dimension registers
38	    reg [DIM_W-1:0] M_reg, K_reg, N_reg;
39	    reg             use_bias_reg;
40	
41	    // Tiling registers
42	    reg [DIM_W-1:0] mt, nt;
43	    reg [DIM_W-1:0] mt_count, nt_count;
44	    reg [DIM_W-1:0] m_base, n_base;
45	    reg [DIM_W-1:0] M_tile, N_tile;
46	
47	    // Compute/drain control
48	    reg [DIM_W-1:0] cycle_cnt;
49	    reg [DIM_W-1:0] drain_m, drain_n;
50	    reg pe_en, pe_acc_clear;
51	
52	    wire [DIM_W-1:0] total_cycles = K_reg + PM[DIM_W-1:0] + PN[DIM_W-1:0] - 16'd2;
53	
54	    // --- PE grid (copied from systolic_mesh_s8.v) ---
55	    wire signed [31:0] pe_acc [0:PM*PN-1];
56	    wire signed [7:0] a_wire [0:PM-1][0:PN];
57	    wire signed [7:0] b_wire [0:PM][0:PN-1];
58	
59	    genvar gi, gj;
60	    generate
61	        for (gi = 0; gi < PM; gi = gi + 1) begin : row
62	            for (gj = 0; gj < PN; gj = gj + 1) begin : col
63	                pe_s8 pe_inst (
64	                    .clk      (clk),
65	                    .rst_n    (rst_n),
66	                    .en       (pe_en),
67	                    .acc_clear(pe_acc_clear),
68	                    .a_in     (a_wire[gi][gj]),
69	                    .b_in     (b_wire[gi][gj]),
70	                    .a_out    (a_wire[gi][gj+1]),
71	                    .b_out    (b_wire[gi+1][gj]),
72	                    .acc      (pe_acc[gi*PN+gj])
73	                );
74	            end
75	        end
76	    endgenerate
77	
78	    // --- Left-edge feeding with tile offsets and boundary check ---
79	    generate
80	        for (gi = 0; gi < PM; gi = gi + 1) begin : a_feed
81	            wire [DIM_W-1:0] a_offset = cycle_cnt - gi[DIM_W-1:0];
82	            wire [31:0]      a_addr   = (m_base + gi[DIM_W-1:0]) * K_reg + a_offset;
83	            wire             a_valid  = (state == S_COMPUTE) &&
84	                                        (cycle_cnt >= gi[DIM_W-1:0]) &&
85	                                        (a_offset < K_reg) &&
86	                                        (gi[DIM_W-1:0] < M_tile);
87	            assign a_wire[gi][0] = a_valid ? a_buf[a_addr[15:0]] : 8'sd0;
88	        end
89	    endgenerate
90	
91	    // --- Top-edge feeding with tile offsets and boundary check ---
92	    generate
93	        for (gj = 0; gj < PN; gj = gj + 1) begin : b_feed
94	            wire [DIM_W-1:0] b_offset = cycle_cnt - gj[DIM_W-1:0];
95	            wire [31:0]      b_addr   = b_offset * N_reg + (n_base + gj[DIM_W-1:0]);
96	            wire             b_valid  = (state == S_COMPUTE) &&
97	                                        (cycle_cnt >= gj[DIM_W-1:0]) &&
98	                                        (b_offset < K_reg) &&
99	                                        (gj[DIM_W-1:0] < N_tile);
100	            assign b_wire[0][gj] = b_valid ? b_buf[b_addr[15:0]] : 8'sd0;
101	        end
102	    endgenerate
103	
104	    // --- FSM ---
105	    always @(posedge clk or negedge rst_n) begin
106	        if (!rst_n) begin
107	            state        <= S_IDLE;
108	            done         <= 1'b0;
109	            pe_en        <= 1'b0;
110	            pe_acc_clear <= 1'b0;
111	            cycle_cnt    <= {DIM_W{1'b0}};
112	            M_reg        <= {DIM_W{1'b0}};
113	            K_reg        <= {DIM_W{1'b0}};
114	            N_reg        <= {DIM_W{1'b0}};
115	            use_bias_reg <= 1'b0;
116	            mt           <= {DIM_W{1'b0}};
117	            nt           <= {DIM_W{1'b0}};
118	            mt_count     <= {DIM_W{1'b0}};
119	            nt_count     <= {DIM_W{1'b0}};
120	            m_base       <= {DIM_W{1'b0}};
121	            n_base       <= {DIM_W{1'b0}};
122	            M_tile       <= {DIM_W{1'b0}};
123	            N_tile       <= {DIM_W{1'b0}};
124	            drain_m      <= {DIM_W{1'b0}};
125	            drain_n      <= {DIM_W{1'b0}};
126	        end else begin
127	            case (state)
128	                S_IDLE: begin
129	                    done <= 1'b0;
130	                    if (start) begin
131	                        M_reg        <= M_in;
132	                        K_reg        <= K_in;
133	                        N_reg        <= N_in;
134	                        use_bias_reg <= use_bias;
135	                        mt_count     <= (M_in + 16'd7) >> 3;
136	                        nt_count     <= (N_in + 16'd15) >> 4;
137	                        mt           <= {DIM_W{1'b0}};
138	                        nt           <= {DIM_W{1'b0}};
139	                        m_base       <= {DIM_W{1'b0}};
140	                        n_base       <= {DIM_W{1'b0}};
141	                        M_tile       <= (M_in >= PM[DIM_W-1:0]) ? PM[DIM_W-1:0] : M_in;
142	                        N_tile       <= (N_in >= PN[DIM_W-1:0]) ? PN[DIM_W-1:0] : N_in;
143	                        cycle_cnt    <= {DIM_W{1'b0}};
144	                        pe_en        <= 1'b1;
145	                        pe_acc_clear <= 1'b1;
146	                        state        <= S_COMPUTE;
147	                    end
148	                end
149	
150	                S_COMPUTE: begin
151	                    if (cycle_cnt == {DIM_W{1'b0}})
152	                        pe_acc_clear <= 1'b0;
153	
154	                    if (cycle_cnt == total_cycles) begin
155	                        pe_en   <= 1'b0;
156	                        drain_m <= {DIM_W{1'b0}};
157	                        drain_n <= {DIM_W{1'b0}};
158	                        state   <= S_DRAIN;
159	                    end else begin
160	                        cycle_cnt <= cycle_cnt + 1'b1;
161	                    end
162	                end
163	
164	                S_DRAIN: begin
165	                    c_buf[(m_base + drain_m) * N_reg + (n_base + drain_n)] <=
166	                        pe_acc[drain_m[3:0]*PN + drain_n[4:0]] +
167	                        (use_bias_reg ? bias_buf[m_base + drain_m] : 32'sd0);
168	
169	                    if (drain_n == N_tile - 1'b1) begin
170	                        drain_n <= {DIM_W{1'b0}};
171	                        if (drain_m == M_tile - 1'b1)
172	                            state <= S_NEXT;
173	                        else
174	                            drain_m <= drain_m + 1'b1;
175	                    end else begin
176	                        drain_n <= drain_n + 1'b1;
177	                    end
178	                end
179	
180	                S_NEXT: begin
181	                    if (nt + 1'b1 < nt_count) begin
182	                        nt           <= nt + 1'b1;
183	                        n_base       <= n_base + PN[DIM_W-1:0];
184	                        N_tile       <= ((N_reg - n_base - PN[DIM_W-1:0]) >= PN[DIM_W-1:0])
185	                                        ? PN[DIM_W-1:0]
186	                                        : (N_reg - n_base - PN[DIM_W-1:0]);
187	                        cycle_cnt    <= {DIM_W{1'b0}};
188	                        pe_en        <= 1'b1;
189	                        pe_acc_clear <= 1'b1;
190	                        state        <= S_COMPUTE;
191	                    end else if (mt + 1'b1 < mt_count) begin
192	                        mt           <= mt + 1'b1;
193	                        nt           <= {DIM_W{1'b0}};
194	                        m_base       <= m_base + PM[DIM_W-1:0];
195	                        n_base       <= {DIM_W{1'b0}};
196	                        M_tile       <= ((M_reg - m_base - PM[DIM_W-1:0]) >= PM[DIM_W-1:0])
197	                                        ? PM[DIM_W-1:0]
198	                                        : (M_reg - m_base - PM[DIM_W-1:0]);
199	                        N_tile       <= (N_reg >= PN[DIM_W-1:0]) ? PN[DIM_W-1:0] : N_reg;
200	                        cycle_cnt    <= {DIM_W{1'b0}};
201	                        pe_en        <= 1'b1;
202	                        pe_acc_clear <= 1'b1;
203	                        state        <= S_COMPUTE;
204	                    end else begin
205	                        state <= S_DONE;
206	                    end
207	                end
208	
209	                S_DONE: begin
210	                    done  <= 1'b1;
211	                    state <= S_IDLE;
212	                end
213	
214	                default: state <= S_IDLE;
215	            endcase
216	        end
217	    end
218	
219	endmodule
