1	`timescale 1ns/10ps
2	
3	module tb_tiled_gemm_s8;
4	
5	localparam CYCLE = 20;
6	localparam DIM_W = 16;
7	
8	reg                 clk, rst_n, start;
9	reg  [DIM_W-1:0]    M_in, K_in, N_in;
10	reg                 use_bias;
11	wire                done;
12	
13	tiled_gemm_s8 #(.DIM_W(DIM_W)) DUT (
14	    .clk(clk), .rst_n(rst_n), .start(start),
15	    .M_in(M_in), .K_in(K_in), .N_in(N_in),
16	    .use_bias(use_bias), .done(done));
17	
18	initial clk = 0; always #(CYCLE/2.0) clk = ~clk;
19	
20	integer M_arg, K_arg, N_arg, bias_arg, fout, k;
21	reg [255:0] a_path, b_path, bias_path, out_path;
22	reg [31:0]  cycles;
23	integer mn;
24	
25	initial begin
26	    if (!$value$plusargs("M=%d", M_arg))      M_arg = 4;
27	    if (!$value$plusargs("K=%d", K_arg))      K_arg = 4;
28	    if (!$value$plusargs("N=%d", N_arg))      N_arg = 4;
29	    if (!$value$plusargs("bias=%d", bias_arg)) bias_arg = 0;
30	    if (!$value$plusargs("a=%s",   a_path))    a_path = "vectors/a.hex";
31	    if (!$value$plusargs("b=%s",   b_path))    b_path = "vectors/b.hex";
32	    if (!$value$plusargs("bi=%s",  bias_path)) bias_path = "vectors/bi.hex";
33	    if (!$value$plusargs("out=%s", out_path))  out_path = "vectors/out.hex";
34	
35	    M_in = M_arg[DIM_W-1:0];
36	    K_in = K_arg[DIM_W-1:0];
37	    N_in = N_arg[DIM_W-1:0];
38	    use_bias = bias_arg[0];
39	
40	    rst_n = 1; start = 0;
41	    $readmemh(a_path, DUT.a_buf);
42	    $readmemh(b_path, DUT.b_buf);
43	    if (bias_arg) $readmemh(bias_path, DUT.bias_buf);
44	
45	    #(2*CYCLE); rst_n = 0; #(2*CYCLE); rst_n = 1;
46	    @(negedge clk); start = 1; @(negedge clk); start = 0;
47	
48	    cycles = 0;
49	    while (!done) begin
50	        cycles = cycles + 1;
51	        if (cycles > 200_000_000) begin
52	            $display("TIMEOUT after %0d cycles", cycles); $finish;
53	        end
54	        @(negedge clk);
55	    end
56	
57	    mn = M_arg * N_arg;
58	    fout = $fopen(out_path, "w");
59	    for (k = 0; k < mn; k = k + 1)
60	        $fwrite(fout, "%08x\n", DUT.c_buf[k] & 32'hffffffff);
61	    $fclose(fout);
62	    $display("tiled_gemm_s8 OK M=%0d K=%0d N=%0d bias=%0d cycles=%0d",
63	             M_arg, K_arg, N_arg, bias_arg, cycles);
64	    $finish;
65	end
66	
67	endmodule
